'use strict';
(() => {
  const { lessons, guides, glossary, sharing, menuGroups, menuReference } = window.FIELD_GUIDE;
  const menuEntries = menuGroups.flatMap(group => group.entries.map(entry => ({...entry, group: group.name, guide: menuReference[entry.id.split('-').slice(-1)[0].toUpperCase()]})));
  const STORAGE_KEY = 'first-light-progress-v1';
  const lessonIds = new Set(lessons.map(item => item.id));
  const bookmarkIds = new Set([...lessons.map(item => `lesson/${item.id}`), ...guides.map(item => `guide/${item.id}`)]);
  const main = document.querySelector('#main');
  const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const initialState = () => ({ version: 1, completed: [], bookmarks: [], notes: {}, practice: [], lastLesson: '' });
  function validate(value) {
    if (!value || value.version !== 1 || !Array.isArray(value.completed) || !Array.isArray(value.bookmarks) || !Array.isArray(value.practice) || !value.notes || typeof value.notes !== 'object' || Array.isArray(value.notes)) throw new Error('Unsupported progress file.');
    const notes = {};
    for (const [key, text] of Object.entries(value.notes)) {
      if ((lessonIds.has(key) || key === 'practice') && typeof text === 'string' && text.length <= 20000) notes[key] = text;
    }
    return {version:1, completed:[...new Set(value.completed.filter(id => lessonIds.has(id)))], bookmarks:[...new Set(value.bookmarks.filter(id => bookmarkIds.has(id)))], notes, practice:[...new Set(value.practice.filter(id => Number.isInteger(id) && id >= 0 && id < 5))], lastLesson:lessonIds.has(value.lastLesson) ? value.lastLesson : ''};
  }
  let state = initialState();
  let storageError = '';
  try { const stored = localStorage.getItem(STORAGE_KEY); if (stored) state = validate(JSON.parse(stored)); }
  catch { storageError = 'Saved progress could not be read. You can use this session and export your progress from My notebook.'; }
  let noticeTimer;
  function notice(message) {
    clearTimeout(noticeTimer);
    document.querySelector('#notice').textContent = message;
    noticeTimer = setTimeout(() => { document.querySelector('#notice').textContent = ''; }, 6500);
  }
  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); return true; }
    catch { notice('Browser storage is unavailable or full. Export your progress from My notebook before leaving.'); return false; }
  }
  const progress = () => Math.round(state.completed.length / lessons.length * 100);
  const bookmark = (id, label) => `<button class="bookmark" data-bookmark="${id}" aria-pressed="${state.bookmarks.includes(id)}" aria-label="${state.bookmarks.includes(id) ? 'Unsave' : 'Save'} ${escape(label)}">${state.bookmarks.includes(id) ? 'Saved ✓' : 'Save +'}</button>`;
  const title = (eyebrow, heading, intro) => `<div class="page-head"><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p class="intro">${intro}</p></div>`;
  function referenceImage(timestamp, alt, caption, width = 698, height = 669) {
    const src = `images/${encodeURIComponent(`Screenshot 2026-10-11 ${timestamp}.png`)}`;
    return `<figure class="reference-image"><a href="${src}" target="_blank" rel="noopener noreferrer" aria-label="Open full image: ${escape(alt)}"><img src="${src}" alt="${escape(alt)}" width="${width}" height="${height}" loading="lazy" decoding="async"></a><figcaption>${caption} <a href="${src}" target="_blank" rel="noopener noreferrer">Open full image ↗</a></figcaption></figure>`;
  }
  const progressBar = () => `<div class="progress-track" role="progressbar" aria-label="Lessons completed" aria-valuemin="0" aria-valuemax="${lessons.length}" aria-valuenow="${state.completed.length}"><span style="width:${progress()}%"></span></div><span class="progress-label">${state.completed.length} of ${lessons.length} lessons completed</span>`;
  const lessonCard = lesson => `<article class="card"><div class="card-top"><span class="card-icon" aria-hidden="true">${lesson.symbol}</span>${bookmark(`lesson/${lesson.id}`,lesson.title)}</div><span class="eyebrow">${lesson.category}</span><h3><a class="stretched" href="#lesson/${lesson.id}">${lesson.title}</a></h3><p>${lesson.intro}</p><div class="meta"><span>${lesson.time} MIN READ</span><span>${state.completed.includes(lesson.id) ? 'COMPLETED ✓' : 'EXPLORE ↗'}</span></div></article>`;
  const lessonRow = (lesson, index) => `<a class="lesson-row" href="#lesson/${lesson.id}"><span class="number">${String(index + 1).padStart(2,'0')}</span><div><h3>${lesson.title}</h3><p>${lesson.category.toLowerCase()}</p></div><span class="row-end">${state.completed.includes(lesson.id) ? '<span class="badge">Completed ✓</span>' : `${lesson.time} min`}<span aria-hidden="true">↗</span></span></a>`;
  function home() {
    const next = lessons.find(lesson => !state.completed.includes(lesson.id)) || lessons[0];
    const resume = lessons.find(lesson => lesson.id === state.lastLesson && !state.completed.includes(lesson.id)) || next;
    return `<section class="hero"><div><span class="eyebrow">A LITTLE CURIOSITY. A WHOLE NEW WAY TO SEE.</span><h1>Learn your camera.<br><em>Find your eye.</em></h1><p>Your Sony α6400, a good lens, and somewhere to begin. Build your confidence one small lesson at a time.</p><div class="hero-actions"><a class="button" href="#lesson/${resume.id}">${state.lastLesson ? 'Continue learning' : 'Start with the basics'} <span aria-hidden="true">↗</span></a><a class="text-link" href="#learn">Explore the learning path</a></div></div><div><div class="hero-art" role="img" aria-label="Illustrated landscape with a sun and hills framed by a viewfinder"><div class="sun"></div><div class="hill"></div><div class="hill two"></div><div class="hill three"></div><div class="viewfinder"><span class="cross"></span></div><div class="art-label"><span>NOTICE THE LIGHT</span><span>FRAME YOUR WORLD ↗</span></div></div><div class="art-caption">A little landscape illustration. Your photographs will come later.</div></div></section>
    <div class="stats"><div class="stat"><strong>${String(lessons.length).padStart(2,'0')}</strong><span>lessons to explore</span></div><div class="stat"><strong>${String(state.completed.length).padStart(2,'0')}</strong><span>lessons completed</span></div><div class="stat"><strong>${String(guides.length).padStart(2,'0')}</strong><span>guides for your next shoot</span></div></div>
    <div class="section-head"><h2>Your next small step</h2><a class="text-link" href="#learn">View learning path ↗</a></div><div class="two-column"><section class="resume-card"><div class="lesson-orbit" aria-hidden="true">${resume.symbol}</div><div><span class="eyebrow">${resume.category} · ${resume.time} MIN READ</span><h3>${resume.title}</h3><p>${resume.intro}</p><a class="button" href="#lesson/${resume.id}">Open lesson <span aria-hidden="true">→</span></a></div></section><section class="practice-teaser"><span class="eyebrow">TAKE YOUR CAMERA OUT</span><h3>One object.<br>Three apertures.</h3><p>A window, an everyday object, and ten minutes to discover what f-numbers do.</p><a class="text-link" href="#practice">Try the first assignment ↗</a></section></div>
    <section class="section-space"><div class="section-head"><h2>Meet the three essentials</h2><p>Small changes. Different photographs.</p></div><div class="card-grid">${lessons.slice(1,4).map(lessonCard).join('')}</div></section>`;
  }
  function learn() {
    const stages = [
      {id: undefined, title: '01 / The foundations', intro: 'Understand light, exposure and focus one concept at a time.'},
      {id: 'controls', title: '02 / Camera in practice', intro: 'Set up your camera, learn its controls and explore the confirmed Sigma 18–50mm lens.'},
      {id: 'fieldcraft', title: '03 / Composition & light', intro: 'Arrange the frame and work with the light you already have. Each lesson ends with a small photo assignment.'},
      {id: 'editing', title: '04 / Edit with intention', intro: 'Use one free RAW editor to make natural, polished JPEGs while keeping your originals.'}
    ];
    return title('YOUR LEARNING PATH','Start simple. Build from there.','Follow a stage, or return to a concept whenever you need it.') + progressBar() +
      stages.map(stage=>`<section class="section-space" data-stage="${stage.id || 'foundations'}"><div class="section-head"><h2>${stage.title}</h2><span class="badge">Available now</span></div><p>${stage.intro}</p><div class="lesson-list">${lessons.filter(item=>item.stage===stage.id).map(item=>lessonRow(item,lessons.indexOf(item))).join('')}</div></section>`).join('') +
      `<div class="roadmap"><span class="eyebrow">THE ROAD AHEAD</span><h3>Keep practising, then build on the results.</h3><p>The full menu reference is available with source-linked concise guidance. Next, use the field review on your own camera and apply the editing workflow to your best local originals. Cloud uploads remain separate.</p><a class="text-link" href="#editing">Open the free editing workflow →</a></div><section class="section-space"><h2>A small dictionary for your camera and edits</h2><dl class="glossary">${glossary.map(([term,definition,id])=>`<div><dt><a href="#lesson/${id}">${term}</a></dt><dd>${definition}</dd></div>`).join('')}</dl></section>`;
  }
  function editingPage() {
    const editLessons = lessons.filter(item => item.stage === 'editing');
    return title('FREE EDITING','Make a good photograph look finished.','Use darktable on your MacBook Air M4: free, open-source RAW editing for your Sony a6400 files.') +
      `<div class="callout"><strong>One editor, no subscription.</strong><p>darktable 5.6.2 has an Apple-silicon download and requires macOS 13.5 or newer. Its official support list includes ILCE-6400 with white-balance presets and lens-correction data. Confirm your macOS version before installing; no app was installed or tested on your Mac by this site.</p></div><section class="section-space"><h2>Your professional-looking workflow</h2><ol class="share-workflow"><li><strong>Keep</strong><span>Originals safe</span></li><li><strong>Select</strong><span>Choose the strongest frame</span></li><li><strong>Correct</strong><span>Light, color, framing</span></li><li><strong>Export</strong><span>Share an sRGB JPEG</span></li></ol></section><section class="section-space"><h2>Start here</h2><div class="card-grid">${editLessons.map(lessonCard).join('')}</div></section><section class="section-space"><h2>What “professional” means here</h2><p>A professional-looking edit is usually believable: the subject is clear, bright areas still have texture, skin and neutral objects do not look strangely colored, the crop feels deliberate, and sharpening/noise reduction are subtle. It is not a fixed saturation number. Use the scene recipes as a first test, compare with the original, then reduce any adjustment that calls attention to itself.</p></section><details class="sharing-sources section-space"><summary>Official darktable sources</summary><ul><li><a href="https://www.darktable.org/install/" target="_blank" rel="noopener noreferrer">Installation and macOS requirements</a> · checked 2026-10-12</li><li><a href="https://www.darktable.org/resources/camera-support/" target="_blank" rel="noopener noreferrer">Camera support list</a> · checked 2026-10-12</li></ul></details>`;
  }
  function lessonPage(id) {
    const lesson = lessons.find(item => item.id === id);
    if (!lesson) return notFound();
    state.lastLesson = id; save();
    const index = lessons.indexOf(lesson);
    let diagram = id === 'aperture' ? `<div class="aperture-demo"><div class="aperture-discs"><div><div class="disc" style="--opening:42px"></div><span>f/2.8 · wider</span></div><div><div class="disc" style="--opening:29px"></div><span>f/4</span></div><div><div class="disc" style="--opening:15px"></div><span>f/8 · smaller</span></div></div><p>Schematic illustration of relative openings at the same focal length.</p></div>` : '';
    if (id === 'composition') diagram = `<figure class="composition-demo"><div class="composition-examples"><div><div class="composition-scene centered" aria-hidden="true"><span class="composition-subject"></span></div><strong>Centered</strong><p>Try balance and symmetry.</p></div><div><div class="composition-scene thirds" aria-hidden="true"><span class="composition-subject"></span></div><strong>Off-center</strong><p>Try space beside the subject.</p></div></div><figcaption>Original schematic, not a camera photograph or a rule about which frame is better. The grid illustrates thirds. Compare both arrangements with your own subject.</figcaption></figure>`;
    if (id === 'focus-area') diagram = `<figure class="focus-schematics"><div class="focus-examples">${['Wide','Zone','Flexible Spot'].map((label,i)=>`<div><div class="focus-scene area-${i}" aria-hidden="true"><span class="focus-subject"></span><span class="focus-box"></span></div><strong>${label}</strong></div>`).join('')}</div><figcaption>Illustrative areas, not Sony screen captures. Wide lets the camera choose broadly; Zone narrows the region; Flexible Spot lets you place a small frame.</figcaption></figure>`;
    if (id === 'exposure-controls') diagram = `<div class="table-scroll" role="region" aria-label="Exposure modes" tabindex="0"><table class="sharing-table"><caption>Who chooses what? ISO AUTO lets the camera choose ISO in all three modes.</caption><thead><tr><th scope="col">Mode</th><th scope="col">You choose</th><th scope="col">Camera chooses</th></tr></thead><tbody><tr><th scope="row">A</th><td>Aperture</td><td>Shutter speed</td></tr><tr><th scope="row">S</th><td>Shutter speed</td><td>Aperture</td></tr><tr><th scope="row">M</th><td>Aperture and shutter speed</td><td>ISO only if set to ISO AUTO</td></tr></tbody></table></div>`;
    if (id === 'aperture' || id === 'focal-length') {
      diagram += `<section class="lesson-reference">${referenceImage('115834','Sigma 18–50mm lens showing focal-length markings and the 1:2.8 inscription','Supplied Sigma lens reference.',564,677)}<div><span class="eyebrow">FIND IT ON YOUR LENS</span><h2>${id === 'aperture' ? 'What does “1:2.8” mean?' : 'Read the zoom markings'}</h2><p>${id === 'aperture' ? 'The 1:2.8 inscription describes the widest aperture: f/2.8. It does not mean you must always shoot at f/2.8. You can select a smaller opening, such as f/4 or f/8, using the camera.' : 'The marked numbers 18, 24, 28, 35, and 50 are focal lengths in millimetres. Turn the zoom ring and watch how much of the scene fits into your frame. These numbers describe zoom, not aperture.'}</p><a class="text-link" href="#kit">Explore the camera references ↗</a></div></section>`;
    }
    return `<a class="breadcrumb" href="#learn">← Back to learning path</a><div class="reading-layout"><article class="reading"><span class="eyebrow">LESSON ${String(index+1).padStart(2,'0')} · ${lesson.category} · ${lesson.time} MIN</span><h1>${lesson.title}</h1><p class="intro">${lesson.intro}</p>${lesson.prerequisites?`<p class="prerequisites">Start with: ${lesson.prerequisites.map(id=>`<a href="#lesson/${id}">${lessons.find(item=>item.id===id).title}</a>`).join(' · ')}</p>`:''}<div class="definition"><span class="eyebrow">IN SIMPLE WORDS</span><p>${lesson.definition}</p></div>${diagram}${lesson.sections.map(([heading,body])=>`<section><h2>${heading}</h2><p>${body}</p></section>`).join('')}<section class="exercise"><span class="eyebrow">PUT IT INTO PRACTICE</span><h2>Try it with your camera</h2><p>${lesson.exercise}</p></section><form class="quiz" data-quiz="${id}"><fieldset style="border:0;padding:0;margin:0"><legend>${lesson.question}</legend>${lesson.options.map((option,i)=>`<label><input type="radio" name="answer" value="${i}" required>${escape(option)}</label>`).join('')}<button class="button" type="submit">Check my understanding</button><p class="feedback" aria-live="polite"></p></fieldset></form><div class="lesson-note"><label for="lesson-note">What did you notice?</label><textarea id="lesson-note" data-note="${id}" maxlength="20000" placeholder="One observation, a question, or something to try next…">${escape(state.notes[id] || '')}</textarea><p class="note-hint">Saved in this browser. Export a copy from My notebook to keep it safe.</p></div><div class="actions"><button class="button" data-complete="${id}">${state.completed.includes(id) ? 'Completed ✓ · Mark unfinished' : 'Mark lesson complete ✓'}</button><a class="text-link" href="${index < lessons.length-1 ? `#lesson/${lessons[index+1].id}` : '#practice'}">${index < lessons.length-1 ? 'Next lesson →' : 'Try an assignment →'}</a></div><p class="source-note">Foundations draft · Original explanations for your learning guide. Exact a6400 menu steps are still being checked. Consult the <a href="https://helpguide.sony.net/ilc/1810/v1/en/index.html" target="_blank" rel="noopener noreferrer">Sony Help Guide</a> for camera operation.</p></article><aside class="reading-aside"><span class="eyebrow">YOUR LESSONS</span>${progressBar()}<ol>${lessons.map(item=>`<li><a href="#lesson/${item.id}" ${item.id===id?'aria-current="step"':''}>${item.title}</a></li>`).join('')}</ol>${bookmark(`lesson/${id}`,lesson.title)}<a class="button secondary" href="#practice">Open practice assignment</a></aside></div>`;
  }
  function guideCard(guide) {
    return `<article class="card guide-card" id="guide-${guide.id}"><div class="card-top"><span class="card-icon" aria-hidden="true">${guide.symbol}</span>${bookmark(`guide/${guide.id}`,guide.title)}</div><span class="eyebrow">${guide.tag}</span><h2>${guide.title}</h2><p>${guide.intro}</p><div class="settings">${guide.settings.map(setting=>`<span>${setting}</span>`).join('')}</div><ol>${guide.steps.map(step=>`<li>${step}</li>`).join('')}</ol><a class="text-link" href="#lesson/${guide.lesson}">Understand the settings ↗</a></article>`;
  }
  function guidesPage(id) {
    const selected = id ? guides.filter(guide => guide.id === id) : guides;
    if (!selected.length) return notFound();
    return title('KEEP THESE CLOSE','A starting point for your next shot.','Pick the situation in front of you. Try these settings, check the result, and adjust.') + `<div class="callout">These are starting points, not fixed rules. Light, distance, and movement change what works. Check the camera’s chosen settings and exposure warnings.</div>${id?'<a class="breadcrumb" href="#guides">← All shooting guides</a>':''}<div class="card-grid guide-grid">${selected.map(guideCard).join('')}</div>`;
  }
  const checks = ['Place an object near a window, away from the background.', 'Use Aperture Priority (A); keep position, zoom, and focus consistent.', 'Take photos at f/2.8, f/4, and f/8 where supported. Steady the camera if needed.', 'Compare background blur and read the shutter speed and ISO for each photo.', 'Write one observation and one thing to try next.'];
  function practice() {
    return title('ASSIGNMENT 01 · ABOUT 10 MINUTES','One object. Three apertures.','Make a small change, then look carefully. This is where the lesson becomes your own experience.') + `<div class="callout">Next assignment: <a href="#lesson/better-photos">Make a photo you prefer to your phone’s</a>. Compare sharpness, light, background and detail with equipment you already own. Continue with <a href="#lesson/composition">composition pairs</a> and the <a href="#lesson/available-light">window-light assignment</a>.</div><div class="two-column"><section class="card"><span class="eyebrow">YOUR SHOOTING CHECKLIST</span><h2>Let the background tell the story.</h2><ul class="checklist">${checks.map((check,index)=>`<li><label><input type="checkbox" data-check="${index}" ${state.practice.includes(index)?'checked':''}>${check}</label></li>`).join('')}</ul><a class="text-link" href="#lesson/aperture">Revisit the aperture lesson ↗</a></section><section class="practice-teaser"><span class="eyebrow">LOOK, THEN ASK</span><h3>What changed?</h3><p>Which background is most blurred? Is the part you focused on still sharp? Did the camera change shutter speed or ISO to keep brightness similar?</p><p>You do not need a beautiful subject. A cup, a plant, or a book is enough.</p><span class="badge">Use what you already own</span></section></div><div class="lesson-note"><label for="practice-note">My observation</label><textarea id="practice-note" data-note="practice" maxlength="20000" placeholder="At f/2.8 I noticed… At f/8… Next time I will…">${escape(state.notes.practice||'')}</textarea><p class="note-hint">Text is saved in this browser. Photo uploads will arrive in the private journal phase.</p></div>`;
  }
  function notebook() {
    const savedLessons=lessons.filter(item=>state.bookmarks.includes(`lesson/${item.id}`));
    const savedGuides=guides.filter(item=>state.bookmarks.includes(`guide/${item.id}`));
    const notes=Object.entries(state.notes).filter(([,value])=>value.trim());
    return title('MY NOTEBOOK','Keep what you’re discovering.','Your saved lessons, small observations, and the progress you are making.') + `<div class="callout">Stored only in this browser, with no account or automatic device sync. Clearing browser data can remove it. Export your progress and notes to keep a backup or move them to another device.</div>${progressBar()}<div class="actions"><button class="button" id="export">Export progress & notes ↓</button><label class="button secondary file-label" for="import">Import & merge progress ↑</label><input class="sr-only" id="import" type="file" accept=".json,application/json"></div><p class="note-hint">Import combines checklists and bookmarks. Existing notes are kept; different imported notes are appended.</p><section class="notebook-section"><h2>Saved for later</h2>${savedLessons.length || savedGuides.length ? `<div class="card-grid">${savedLessons.map(lessonCard).join('')}${savedGuides.map(guide=>`<article class="card"><span class="eyebrow">SHOOTING GUIDE</span><h3><a class="stretched" href="#guide/${guide.id}">${guide.title}</a></h3><p>${guide.intro}</p></article>`).join('')}</div>` : '<div class="empty-state">Use “Save +” on a lesson or shooting guide to find it here.</div>'}</section><section class="notebook-section"><h2>My observations</h2>${notes.length ? notes.map(([id,value])=>`<article class="note-card"><h3>${id==='practice'?'First aperture assignment':lessons.find(item=>item.id===id).title}</h3><p>${escape(value)}</p><a href="${id==='practice'?'#practice':`#lesson/${id}`}">Return to edit →</a></article>`).join('') : '<div class="empty-state">Write an observation at the end of a lesson or practice assignment. It will appear here.</div>'}</section><div class="roadmap"><span class="eyebrow">LATER PHASE</span><h3>A private home for your photographs</h3><p>The photo journal will add protected uploads and image comparisons. This notebook currently stores text and progress only.</p></div>`;
  }
  function kit() {
    return title('MY SETUP','Get to know what’s in your hands.','Your camera, your lens, and the controls you will reach for most. Open any reference image for a closer look.') +
      `<div class="callout">Body: ILCE-6400, firmware 2.00. Lens firmware: 03. Body/lens versions and Sigma 18–50mm F2.8 DC DN | Contemporary, Sony E mount, confirmed 2026-10-11. <a href="#lesson/first-day">First-day setup →</a> · <a href="#camera">Camera menu reference →</a></div><div class="card-grid guide-grid"><section class="card"><span class="eyebrow">YOUR CAMERA · TOP VIEW</span><h2>Sony α6400</h2>${referenceImage('115558','Annotated Sony a6400 top view showing the power switch, mode dial, control dial, flash, and accessory shoe','Start with the mode dial and power switch.')}<ul class="equipment-notes"><li><strong>4 · Power switch:</strong> turn the camera on and off.</li><li><strong>6 · Mode dial:</strong> choose A for aperture priority, S for shutter priority, or M to set both.</li><li><strong>7 · Control dial:</strong> adjust settings; what it controls depends on your mode and customization.</li></ul><a class="text-link" href="https://helpguide.sony.net/ilc/1810/v1/en/index.html" target="_blank" rel="noopener noreferrer">Official Sony Help Guide ↗</a></section>
      <section class="card"><span class="eyebrow">YOUR LENS · READ THE MARKINGS</span><h2>Sigma 18–50mm F2.8</h2>${referenceImage('115834','Sigma 18–50mm F2.8 lens without its hood, with zoom and aperture markings visible','18–50mm is the focal-length range. 1:2.8 describes the maximum aperture.',564,677)}<p>Use the wider end to include more surroundings, or the longer end for tighter framing. The f/2.8 marking describes the widest opening; you can also choose smaller openings.</p><p>Verified Sony E specifications: closest focus 12.1 cm at 18mm and 30 cm at 50mm, measured from the sensor plane; 55mm filter thread. Start farther away for comfortable close-ups.</p><a class="text-link" href="#lesson/lens-fieldwork">Explore your lens and its limits ↗</a></section></div>
      <section class="section-space"><div class="section-head"><h2>Around the camera</h2><span class="badge">Supplied references</span></div><div class="card-grid guide-grid"><article class="card"><h3>Battery, card & tripod</h3>${referenceImage('115613','Sony a6400 underside showing the access lamp, battery and memory-card compartment, and tripod socket','The battery/card compartment is under the grip.')}<p>Identify the compartment before your first shoot. Wait for card activity to finish before removing the battery or memory card. The tripod socket secures the camera to a compatible support.</p></article><article class="card"><h3>Connections on the side</h3>${referenceImage('115629','Sony a6400 side views with Micro USB, Micro HDMI and microphone connections labeled','These connectors have different shapes and purposes.')}<p>Use this view to recognize the USB, HDMI, and microphone connections. Check the camera manual and the cable type before connecting equipment.</p></article></div></section>
      <section class="section-space"><h2>Meet the lens hood</h2><div class="card-grid guide-grid"><article class="card">${referenceImage('115753','Sigma 18–50mm lens with a petal-shaped hood attached','The hood fitted to the lens.',486,668)}<p>A hood helps block stray light arriving from outside the picture. It may reduce flare, but does not remove every reflection.</p></article><article class="card">${referenceImage('115810','Separate petal-shaped lens hood with its alignment mark visible','The same style of hood on its own.',752,584)}<p>The hood is not a lens cap. Light still passes through the centre. Align and attach the matching hood according to the lens instructions.</p></article></div></section>
      <section class="section-space"><h2>Your learning and editing devices</h2><div class="card-grid"><article class="card"><span class="eyebrow">MAIN EDITING DEVICE · LATER</span><h3>MacBook Air M4</h3><p>Photo organization and editing with free software. We’ll choose an editor in a later phase.</p></article><article class="card"><span class="eyebrow">READ & REVIEW</span><h3>Galaxy Tab S9</h3><p>Read lessons and review your photographs. Notes currently stay in the browser where you write them.</p></article><article class="card"><span class="eyebrow">TAKE IT WITH YOU</span><h3>Nothing Phone (2)</h3><p>Keep a shooting guide beside your camera and record a quick observation after practice.</p></article></div></section><div class="roadmap"><h3>A free learning setup</h3><p>This local guide needs no subscription or account. Private photo uploads and editing lessons remain in later phases. These are supplied equipment reference images, not photographs taken with your camera.</p></div>`;
  }
  function searchPage(query) {
    const q = query.trim().toLowerCase();
    const matchedLessons = q ? lessons.filter(item=>JSON.stringify(item).toLowerCase().includes(q)) : [];
    const matchedGuides = q ? guides.filter(item=>JSON.stringify(item).toLowerCase().includes(q)) : [];
    const matchedTerms = q ? glossary.filter(item=>item.slice(0,2).join(' ').toLowerCase().includes(q)) : [];
    return title('FIND A CONCEPT',q?`Results for “${escape(query.trim())}”`:'What would you like to learn?', 'Search the available lessons, shooting guides, and glossary.') + (matchedLessons.length||matchedGuides.length||matchedTerms.length ? `${matchedLessons.length?`<h2>Lessons</h2><div class="card-grid">${matchedLessons.map(lessonCard).join('')}</div>`:''}${matchedGuides.length?`<section class="section-space"><h2>Shooting guides</h2><div class="card-grid guide-grid">${matchedGuides.map(guideCard).join('')}</div></section>`:''}${matchedTerms.length?`<section class="section-space"><h2>Glossary</h2><dl class="glossary">${matchedTerms.map(([term,definition,id])=>`<div><dt><a href="#lesson/${id}">${term}</a></dt><dd>${definition}</dd></div>`).join('')}</dl></section>`:''}` : '<div class="empty-state">Try “aperture”, “movement”, “portrait”, or “ISO”. More lessons will be added as your guide grows.</div>');
  }
  const externalLink = (label, url) => `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a>`;
  function sharingMethod(method) {
    return `<article class="sharing-method"><span class="eyebrow">${method.tag}</span><h2>${method.title}</h2><p class="intro">${method.intro}</p><ol class="sharing-steps">${method.steps.map(step=>`<li>${step}</li>`).join('')}</ol><div class="callout"><strong>Keep in mind:</strong> ${method.tradeoff}</div>${method.source?`<p class="source-note">${externalLink('Official instructions',method.source)}</p>`:''}</article>`;
  }
  function sharingPage(id) {
    if(id){
      const method=sharing.methods.find(item=>item.id===id);
      if(!method)return notFound();
      return `<a class="breadcrumb" href="#share">← All sharing options</a>`+title('SHARE YOUR PHOTOGRAPHS',method.title,method.intro)+`<div class="sharing-detail">${sharingMethod(method)}<a class="button secondary" href="#lesson/file-format">Understand JPEG and RAW →</a></div>`;
    }
    return title('FROM YOUR CAMERA TO THEIR DAY','Good photographs are worth sharing.','Choose a simple way to send your favorites. Keep your originals, share the right copy, and make it easy for people to open.')+
      `<section class="card-grid sharing-picks"><article class="card"><span class="eyebrow">FOR DOWNLOADS & PRINTS</span><h2>Google Drive</h2><p>My first choice when family should download the exact JPEG you upload.</p><a class="button" href="#share/drive">Make a download link ↗</a></article><article class="card"><span class="eyebrow">FOR A FAMILY ALBUM</span><h2>Google Photos</h2><p>An easy browsing experience for a trip, celebration, or collection of memories.</p><a class="button secondary" href="#share/album">Share an album ↗</a></article><article class="card"><span class="eyebrow">FOR YOUR NEARBY DEVICES</span><h2>LocalSend</h2><p>Move files between your Mac, Tab S9, and Nothing Phone over a local network.</p><a class="button secondary" href="#share/nearby">Transfer nearby ↗</a></article></section>
      <section class="section-space"><h2>A simple workflow for your setup</h2><ol class="share-workflow"><li><strong>Copy</strong><span>Camera → Mac</span></li><li><strong>Select</strong><span>Keep the best few</span></li><li><strong>Prepare</strong><span>JPEGs for viewing</span></li><li><strong>Share</strong><span>An album or file link</span></li></ol><div class="two-column"><article class="card"><span class="eyebrow">FIRST, GET THE FILES</span><h3>Import to your MacBook Air</h3><p>With a compatible data cable you already own, connect the camera and turn it on. Open the Mac’s built-in Image Capture, select the camera, choose an import folder, then Download selected files or Download All.</p><p>If the camera is not recognized, check Sony’s USB Connection instructions. Sony documents turning Ctrl w/ Smartphone off before changing USB Connection; Auto and Mass Storage are import options. PC Remote serves a different workflow.</p><p>If you already own a compatible card reader, copying from the SD card is another option. Check the imported files and keep the card originals until you have a dependable backup.</p><p class="source-note">${externalLink('Apple import guide',sharing.sources[6][1])} · ${externalLink('Sony USB settings',sharing.sources[7][1])}</p></article><article class="card"><span class="eyebrow">A QUICK PHONE ROUTE</span><h3>Camera → phone → family</h3><p>The a6400’s Send to Smartphone feature can transfer viewing copies wirelessly. Sony’s older manual calls the app PlayMemories Mobile; Sony documents its later name as Imaging Edge Mobile. Check current device support before setting it up.</p><p>The camera path is MENU → Network → Send to Smartphone Func. → Send to Smartphone. Follow the pairing instructions shown by the camera and app.</p><p>Check transfer size: Sony lists Original, 2M, and VGA. RAW images are converted to JPEG when sent this way, so this is not an original-RAW backup. Detailed pairing screenshots for your phone remain planned.</p><p class="source-note">${externalLink('Sony phone transfer guide',sharing.sources[8][1])} · ${externalLink('Sony mobile support',sharing.sources[9][1])}</p></article></div></section>
      <section class="section-space"><div class="section-head"><h2>Free storage you can share by link</h2><span class="badge">Checked ${sharing.checked}</span></div><div class="table-scroll" role="region" aria-label="Free storage comparison" tabindex="0"><table class="sharing-table"><caption>Personal free plans. Check your remaining space before uploading.</caption><thead><tr><th scope="col">Service</th><th scope="col">Free allowance</th><th scope="col">Best for</th><th scope="col">What to know</th></tr></thead><tbody>${sharing.providers.map(provider=>`<tr><th scope="row">${externalLink(provider.name,provider.url)}</th><td>${provider.allowance}</td><td>${provider.best}</td><td>${provider.limit}</td></tr>`).join('')}</tbody></table></div><p class="note-hint">Google Drive and Google Photos use the same allowance, not two separate 15 GB pools. No free plan here offers unlimited storage. Share selected copies and clear unneeded cloud files only after keeping your own backup; a paid upgrade is not part of this workflow.</p></section>
      <section class="section-space"><h2>Choose the right file before sending</h2><div class="card-grid"><article class="card"><span class="eyebrow">KEEP FOR YOURSELF</span><h3>Your capture originals</h3><p>Keep the original JPEG and, if captured, RAW. Share from copies so that resizing or app compression does not replace your only original.</p></article><article class="card"><span class="eyebrow">FOR EVERYDAY VIEWING</span><h3>A JPEG that opens easily</h3><p>Use the camera JPEG now. Later, an sRGB JPEG export around 2,000–3,000 pixels on the long edge is a practical viewing copy, not a mandatory size. Resize a copy only when it helps save data.</p></article><article class="card"><span class="eyebrow">FOR PRINTING & DETAIL</span><h3>A full-resolution JPEG</h3><p>Offer a download of the full-resolution JPEG and tell recipients to download it, not screenshot the preview. Retain RAW for your editing workflow unless someone specifically needs it.</p></article></div><div class="actions"><a class="button secondary" href="#lesson/file-format">Read the JPEG / RAW lesson →</a></div></section>
      <section class="section-space"><h2>All the practical sharing routes</h2><p class="intro">Choose the method that fits the recipient, the quality you need, and whether you are nearby.</p><div class="lesson-list">${sharing.methods.map(method=>`<a class="lesson-row" href="#share/${method.id}"><div><h3>${method.title}</h3><p>${method.intro}</p></div><span class="row-end" aria-hidden="true">↗</span></a>`).join('')}</div></section>
      <section class="section-space"><h2>Give the right people the right access</h2><div class="two-column"><article class="card"><h3>Restricted or anyone with the link?</h3><p>Restricted sharing limits access to the people you invite, who may need to sign in. “Anyone with the link” is convenient, but that link can be forwarded. Use Viewer access for ordinary family delivery.</p><p>Review which photographs and any location metadata you are sharing. Prefer a selected album or folder over automatic sharing of an entire library.</p></article><article class="card"><h3>A shared copy is not your backup</h3><p>Keep originals separately. Removing an album link or changing permissions does not retrieve files somebody already downloaded.</p><p>This page teaches you to use those services yourself. Uploading from this website into your private photo journal is a separate, later feature.</p></article></div></section>
      <details class="sharing-sources section-space"><summary>Official sources and verification dates</summary><p>Checked ${sharing.checked}. Account rules and app screens can change. The workflow and export-size suggestions are recommendations; generic chat, email, and removable-drive advice has no promised service-specific limits.</p><ul>${sharing.sources.map(([label,url])=>`<li>${externalLink(label,url)}</li>`).join('')}</ul></details>`;
  }
  const menuRow = entry => `<a class="lesson-row menu-row" href="#menu/${entry.id}"><div><h3>${escape((entry.guide && entry.guide.label) || entry.label)}</h3><p>${escape(entry.group)} · ${entry.guide ? 'Explained in this guide' : 'Official source · explanation planned'}</p></div><span class="row-end" aria-hidden="true">↗</span></a>`;
  function cameraPage(query = '') {
    const q = query.trim().toLowerCase();
    const matches = menuEntries.filter(entry => `${entry.label} ${entry.group} ${entry.guide ? JSON.stringify(entry.guide) : ''}`.toLowerCase().includes(q));
    return title('CAMERA REFERENCE','Find a setting. Understand what it does.','Use the short camera lessons first, then look up a menu setting when you need it.') +
      `<div class="callout"><strong>${menuEntries.filter(entry=>entry.guide).length} explained entries · ${menuEntries.length} indexed Sony topics · 6 menu groups.</strong><p>The inventory follows Sony’s English “List of MENU items,” including linked subtopics. It is not a count of unique camera switches. Every topic has concise guidance and a Sony source; nested catalogs not enumerated by Sony remain marked for on-camera review.</p><p>Your body firmware: 2.00; lens firmware: 03 (reported 2026-10-11). New source checks are dated 2026-10-12. Instructions have not yet been tested on your physical camera.</p></div>
      <div class="actions"><a class="button" href="#lesson/first-day">Start with camera setup →</a><a class="button secondary" href="#lesson/focus-area">Practise autofocus →</a></div>
      <form id="menu-search" class="menu-search" role="search"><label for="menu-query">Find a menu topic or problem</label><div><input id="menu-query" type="search" maxlength="100" value="${escape(query)}" placeholder="Try Focus Area or JPEG"><button class="button" type="submit">Find</button></div></form>
      <nav class="menu-groups" aria-label="Filter menu groups"><a href="#camera" ${!q?'aria-current="page"':''}>All groups</a>${menuGroups.map(group=>`<a href="#camera/${encodeURIComponent(group.name)}" ${q===group.name.toLowerCase()?'aria-current="page"':''}>${escape(group.name)}</a>`).join('')}</nav>
      <p role="status">${matches.length} matching topics${q?` for “${escape(query)}”`:''}.</p>
      ${matches.length ? menuGroups.map(group=>{const entries=matches.filter(entry=>entry.group===group.name);return entries.length?`<details class="menu-section" ${q?'open':''}><summary>${escape(group.name)} <span>${entries.length} topics · ${entries.filter(entry=>entry.guide).length} explained</span></summary><div class="lesson-list">${entries.map(menuRow).join('')}</div></details>`:'';}).join('') : '<div class="empty-state">No matching menu topics. Try a shorter term, such as “focus”, or choose All groups.</div>'}`;
  }
  function menuPage(id) {
    const entry = menuEntries.find(entry=>entry.id===id);
    if (!entry) return notFound();
    const guide = entry.guide;
    return `<a class="breadcrumb" href="#camera/${encodeURIComponent(entry.group)}">← ${escape(entry.group)}</a>` + title('SONY A6400 MENU',escape((guide && guide.label) || entry.label),guide?escape(guide.meaning):'This topic is in the official menu inventory. Its explanation in First Light is still planned.') +
      (guide ? `<article class="reading menu-reading"><div class="definition"><span class="eyebrow">FIND IT ON THE CAMERA</span><p>${escape(guide.path)}</p></div><section><h2>Choices and what they do</h2><ul>${guide.choices.map(choice=>`<li>${escape(choice)}</li>`).join('')}</ul></section><section><h2>A starting point</h2><p>${escape(guide.start)}</p></section><section><h2>Limits and unavailable settings</h2><p>${escape(guide.limits)}</p></section><section><h2>What this affects</h2><p>${escape(guide.affects)}</p></section><a class="button secondary" href="#lesson/${guide.lesson}">Try the related lesson →</a><p class="source-note">Explanation checked ${entry.source.checked} against ${externalLink(entry.source.label,entry.source.url)}. Suggestions are starting points; physical-camera testing is pending.</p>${guide.sources?`<details class="sharing-sources"><summary>Related official instructions</summary><ul>${guide.sources.map(source=>`<li>${externalLink(source.label,source.url)} · checked ${escape(source.checked)}</li>`).join('')}</ul></details>`:''}</article>` : `<div class="callout">A linked manual topic is not a finished lesson. Use ${externalLink('Sony’s official instructions',entry.source.url)} for the available choices, restrictions and operation. Inventory checked ${entry.source.checked}. <a href="#lesson/first-day">Start with the available setup lesson</a>.</div>`);
  }
  const notFound = () => title('PAGE NOT FOUND','Let’s get you back to learning.','This page is not part of the current guide.') + '<a class="button" href="#learn">Open learning path →</a>';
  function render(focus = false) {
    const route = location.hash.slice(1) || 'home';
    const [page, ...parts] = route.split('/');
    let detail; try { detail = decodeURIComponent(parts.join('/')); } catch { detail = ''; }
    const renderers = {home, learn, lesson:()=>lessonPage(detail), guides:()=>guidesPage(), guide:()=>guidesPage(detail), editing:editingPage, practice, notebook, kit, share:()=>sharingPage(detail), camera:()=>cameraPage(detail), menu:()=>menuPage(detail), search:()=>searchPage(detail)};
    main.innerHTML = (Object.prototype.hasOwnProperty.call(renderers,page) ? renderers[page] : notFound)();
    if(page==='practice'){
      const assignments=lessons.filter(item=>['portrait-light-assignment','indoor-light-assignment','backlit-assignment'].includes(item.id));
      main.querySelector('.callout').insertAdjacentHTML('afterend',`<section class="section-space practice-assignments"><h2>Put composition and light together</h2><p>Each assignment has its own review prompts and notebook space. Save the actual settings and one observation after your shoot.</p><div class="card-grid">${assignments.map(lessonCard).join('')}</div></section>`);
    }
    if(page==='lesson'){
      const lesson=lessons.find(item=>item.id===detail);
      if(lesson && lesson.sources){
        const note=main.querySelector('.source-note');
        note.innerHTML=lesson.sourceNote ? escape(lesson.sourceNote) : `Camera instructions checked 2026-10-11 against Sony’s English a6400 guide. Practical settings and assignments are recommendations, not guaranteed results. Physical-camera walkthrough testing remains pending.${detail==='better-photos'?' No flagship-phone comparison has been performed.':''}`;
        note.insertAdjacentHTML('afterend',`<details class="sharing-sources"><summary>Official sources for this lesson</summary><ul>${lesson.sources.map(source=>`<li>${externalLink(source.label,source.url)} · checked ${escape(source.checked)}</li>`).join('')}</ul></details>`);
        const related=menuEntries.filter(entry=>entry.guide && !entry.guide.generated && entry.guide.lesson===detail);
        if(related.length) note.insertAdjacentHTML('beforebegin',`<details class="sharing-sources"><summary>Related menu explanations (${related.length})</summary><ul>${related.map(entry=>`<li><a href="#menu/${entry.id}">${escape(entry.guide.label)}</a></li>`).join('')}</ul></details>`);
      }
      if(lesson && lesson.source){
        main.querySelector('.source-note').innerHTML=`Camera setting checked ${lesson.source.checked} against ${externalLink(lesson.source.label,lesson.source.url)}. Practical exercises are starting points for your own testing.${detail==='file-format'?` Phone-transfer behavior: ${externalLink('Sony Send to Smartphone',sharing.sources[8][1])}. <a href="#share">Explore sharing options →</a>`:''}`;
      }
    }
    if(page==='search' && detail.trim()){
      const menuMatches=menuEntries.filter(entry=>`${entry.label} ${entry.group} ${entry.guide?JSON.stringify(entry.guide):''}`.toLowerCase().includes(detail.trim().toLowerCase()));
      if(menuMatches.length){
        const empty=main.querySelector('.empty-state'); if(empty)empty.remove();
        main.insertAdjacentHTML('beforeend',`<section class="section-space"><h2>Camera menu topics (${menuMatches.length})</h2><div class="lesson-list">${menuMatches.slice(0,12).map(menuRow).join('')}</div>${menuMatches.length>12?`<a class="text-link" href="#camera/${encodeURIComponent(detail)}">See all matching menu topics →</a>`:''}</section>`);
      }
      const matches=sharing.methods.filter(method=>JSON.stringify(method).toLowerCase().includes(detail.trim().toLowerCase()));
      if(matches.length){
        const empty=main.querySelector('.empty-state');if(empty)empty.remove();
        main.insertAdjacentHTML('beforeend',`<section class="section-space"><h2>Sharing guides</h2><div class="lesson-list">${matches.map(method=>`<a class="lesson-row" href="#share/${method.id}"><div><h3>${method.title}</h3><p>${method.intro}</p></div><span class="row-end" aria-hidden="true">↗</span></a>`).join('')}</div></section>`);
      }
    }
    const currentLesson = page === 'lesson' ? lessons.find(item => item.id === detail) : null;
    const active = currentLesson && currentLesson.stage === 'editing' ? 'editing' : ({lesson:'learn',guide:'guides',search:'learn',menu:'camera'}[page] || page);
    document.querySelectorAll('[data-nav]').forEach(link=> { if(link.dataset.nav===active) link.setAttribute('aria-current','page'); else link.removeAttribute('aria-current'); });
    const heading = main.querySelector('h1');
    document.title = `${heading ? heading.textContent : 'Your field guide'} — First Light`;
    if(focus){ window.scrollTo(0,0); main.focus({preventScroll:true}); }
  }
  document.querySelector('#search-form').addEventListener('submit',event=>{event.preventDefault();location.hash=`search/${encodeURIComponent(document.querySelector('#search').value.trim())}`;});
  main.addEventListener('click',event=>{
    const button=event.target.closest('button'); if(!button)return;
    if(button.dataset.bookmark){ const id=button.dataset.bookmark; state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(item=>item!==id):[...state.bookmarks,id];save();const active=state.bookmarks.includes(id);button.setAttribute('aria-pressed',String(active));button.textContent=active?'Saved ✓':'Save +';button.setAttribute('aria-label',`${active?'Unsave':'Save'} ${id.startsWith('lesson/')?lessons.find(item=>`lesson/${item.id}`===id).title:guides.find(item=>`guide/${item.id}`===id).title}`); }
    if(button.dataset.complete){const id=button.dataset.complete;state.completed=state.completed.includes(id)?state.completed.filter(item=>item!==id):[...state.completed,id];const persisted=save();render();main.querySelector('[data-complete]').focus({preventScroll:true});if(persisted)notice(state.completed.includes(id)?'Lesson completed. Try the exercise to make it stick.':'Lesson marked unfinished.');}
    if(button.id==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='first-light-progress.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Progress export prepared. Keep the downloaded file as your backup.');}
  });
  main.addEventListener('input',event=>{const id=event.target.dataset.note;if(id){state.notes[id]=event.target.value;save();}});
  main.addEventListener('change',async event=>{
    if(event.target.dataset.check!==undefined){const id=Number(event.target.dataset.check);state.practice=event.target.checked?[...new Set([...state.practice,id])]:state.practice.filter(item=>item!==id);save();}
    if(event.target.id==='import'){
      const file=event.target.files[0];if(!file)return;
      try{
        if(file.size>1000000)throw new Error('File is too large. Choose a First Light JSON export under 1 MB.');
        const imported=validate(JSON.parse(await file.text()));
        const mergedNotes={...state.notes};
        for(const [id,note] of Object.entries(imported.notes)){
          if(!mergedNotes[id])mergedNotes[id]=note;
          else if(note && mergedNotes[id]!==note && !mergedNotes[id].includes(`\n\nImported note:\n${note}`)){
            const merged=`${mergedNotes[id]}\n\nImported note:\n${note}`;
            if(merged.length>20000)throw new Error('Merged notes would exceed 20,000 characters. Shorten the note before importing.');
            mergedNotes[id]=merged;
          }
        }
        state={version:1,completed:[...new Set([...state.completed,...imported.completed])],bookmarks:[...new Set([...state.bookmarks,...imported.bookmarks])],practice:[...new Set([...state.practice,...imported.practice])],notes:mergedNotes,lastLesson:state.lastLesson||imported.lastLesson};
        const persisted=save();render();if(persisted)notice('Progress merged. Your existing notes were kept.');
      }catch(error){notice(`Import not applied: ${error instanceof SyntaxError?'this is not valid JSON.':error.message}`);}
      event.target.value='';
    }
  });
  main.addEventListener('submit',event=>{if(event.target.id==='menu-search'){event.preventDefault();location.hash=`camera/${encodeURIComponent(document.querySelector('#menu-query').value.trim())}`;return;}if(!event.target.dataset.quiz)return;event.preventDefault();const lesson=lessons.find(item=>item.id===event.target.dataset.quiz);const value=new FormData(event.target).get('answer');if(value===null)return;const correct=Number(value)===lesson.answer;event.target.querySelector('.feedback').textContent=`${correct?'That’s right.':'Try again.'} ${lesson.explanation}`;});
  window.addEventListener('hashchange',()=>render(true));
  render();
  if(storageError)notice(storageError);
})();
